const collisions = [];
const seen = new Set();
const kept = [];
for (const row of rows) {
  const id = row[0];
  if (existingIds.has(id) || seen.has(id)) {
    collisions.push(id);
    continue;
  }
  seen.add(id);
  kept.push(row);
}

if (collisions.length) {
  console.error("SKIPPED collisions:", collisions.join(", "));
}

const lines = kept.map((row) => {
  const [id, name, kind, state, ahj, portal, url, county, note] = row;
  const countyArg = county ? JSON.stringify(county) : "undefined";
  const noteArg = note ? `, ${JSON.stringify(note)}` : "";
  if (note) {
    return `  p(${JSON.stringify(id)}, ${JSON.stringify(name)}, ${JSON.stringify(kind)}, ${JSON.stringify(state)}, ${JSON.stringify(ahj)}, ${JSON.stringify(portal)}, ${JSON.stringify(url)}, ${countyArg}${noteArg}),`;
  }
  if (county) {
    return `  p(${JSON.stringify(id)}, ${JSON.stringify(name)}, ${JSON.stringify(kind)}, ${JSON.stringify(state)}, ${JSON.stringify(ahj)}, ${JSON.stringify(portal)}, ${JSON.stringify(url)}, ${JSON.stringify(county)}),`;
  }
  return `  p(${JSON.stringify(id)}, ${JSON.stringify(name)}, ${JSON.stringify(kind)}, ${JSON.stringify(state)}, ${JSON.stringify(ahj)}, ${JSON.stringify(portal)}, ${JSON.stringify(url)}),`;
});

const out = `import type { PlaceDesk } from "./types";
import { p } from "./places-extra";

/**
 * Remaining named AHJs — no overlap with CORE_PLACES or EXTRA_PLACES ids.
 * Large remaining cities (typically 50k+), additional counties, and U.S. territories.
 * Official department / municipal landing pages. Guidance only.
 */
export const MORE_PLACES: PlaceDesk[] = [
${lines.join("\n")}
];
`;

writeFileSync("/workspace/src/lib/permit/places-more.ts", out);
console.log(`wrote ${kept.length} places (${collisions.length} skipped)`);
